"use strict";(globalThis.webpackChunkgrc||=[]).push([[62920],{38096(e){e.exports=JSON.parse('{"citeKey":"chanchio2004communicationstate","slug":"chanchio-2004-communication-state-dd5a","title":"Communication State Transfer for the Mobility of Concurrent Heterogeneous Computing","authors":["K. Chanchio","X.-H. Sun"],"venue":"IEEE Trans. on Computers, vol. 53, no. 10, pp. 1260-1273","type":"Journal","entryType":"article","date":"January, 2004","year":2004,"era":"iit","month":1,"doi":"10.1109/tc.2004.73","abstract":"In a dynamic environment where a process can migrate from one host to another host, communication state transfer is a key issue of process coordination. This paper presents a set of data communication and process migration protocols to support communication state transfer in a dynamic, distributed parallel environment. The protocols preserve the semantics of point-to-point communication; they guarantee message delivery, maintain message ordering, and do not introduce deadlock when blocking send or receive operations are performed during process migration. Analytical proofs and prototype implementation are conducted to confirm the correctness of the protocols. Analytical and experimental results show the proposed design is valid and has a true potential in network computing.","hasAbstract":true,"lede":"This paper presents a set of data communication and process migration protocols to support communication state transfer in a dynamic, distributed parallel environment.","links":{"pdf":"https://grc.iit.edu/papers/2004/chanchio-2004-communication-state-dd5a.pdf"},"_projectIds":[],"grcSelected":false,"status":"published","visibility":"public","projectIds":["hpcm"],"memberAuthors":["sun-xian-he"]}')}}]);